228	 * Validate one destination's declaration and put it in slot order.
229	 *
230	 * Absent and `[]` both mean "no credentials here", which is the normal case and
231	 * not a problem. Anything else that cannot be honoured exactly is a problem:
232	 * this returns names only when every one of them is usable, because a partially
233	 * applied credential list gives the process a confusing runtime failure instead
234	 * of a configuration error anyone can act on.
235	 */
236	export function resolveDeclaredSecrets(raw: unknown, destination: SecretDestination): SecretsResolution {
237	  const { field, reserved } = destination;
238	  if (raw === undefined || raw === null) return { names: [], problems: [] };
239	
240	  if (!Array.isArray(raw)) {
241	    return { names: [], problems: [`\`${field}\` must be an array of secret names.`] };
242	  }
243	
244	  const problems: string[] = [];
245	  const names: string[] = [];
246	  const seen = new Set<string>();
247	
248	  for (const entry of raw) {
249	    if (typeof entry !== "string") {
250	      problems.push(`\`${field}\` entries must be strings; found ${JSON.stringify(entry)}.`);
251	      continue;
252	    }
253	    const name = entry.trim();
254	    if (!NAME_PATTERN.test(name)) {
255	      problems.push(
256	        `\`${field}\`: '${name}' is not a usable secret name. Expected uppercase letters, digits and underscores, starting with a letter — e.g. 'SLACK_TOKEN'.`,
257	      );
258	      continue;
259	    }
260	    if (reserved.has(name)) {
261	      problems.push(
262	        `\`${field}\`: '${name}' is already part of the environment this workflow provides, so declaring it would replace that value rather than add a credential. Give the secret another name.`,
263	      );
264	      continue;
265	    }
266	    if (name.startsWith(SECRET_SLOT_PREFIX)) {
267	      problems.push(
268	        `\`${field}\`: '${name}' collides with the slots this mechanism uses internally. Give the secret another name.`,
269	      );
270	      continue;
271	    }
272	    if (seen.has(name)) {
273	      problems.push(`\`${field}\`: '${name}' is declared more than once.`);
274	      continue;
275	    }
276	    seen.add(name);
277	    names.push(name);
278	  }
